"""Produce student mathematical ideas only; final proofs generated by separate executor."""
import concurrent.futures
import json
import hashlib
from pathlib import Path
import subprocess
import tempfile
import time
from verify import ROOT,HEADER

SCHEMA={"type":"object","properties":{"idea":{"type":"string"}},"required":["idea"],"additionalProperties":False}

def run(r):
    out=ROOT/'rollouts'/'luna-idea-only'/r['id'];out.mkdir(parents=True,exist_ok=False)
    prompt=("Given the exact formal Lean theorem below, propose a concise mathematical idea "
            "for solving it in one or two sentences. Do not write a Lean proof or implement it. "
            "Another model will perform the formal implementation. Do not use tools, files, "
            "shell commands, web or other agents. Return only the idea in JSON.\n\n"+HEADER+'\n'+r['statement'])
    (out/'prompt.txt').write_text(prompt);(out/'schema.json').write_text(json.dumps(SCHEMA,indent=2))
    cmd=['codex','exec','--ignore-user-config','--ephemeral','--skip-git-repo-check','--sandbox','read-only','--color','never','--json','-m','gpt-6-luna','-c','model_reasoning_effort="low"','--output-schema',str(out/'schema.json'),'--output-last-message',str(out/'answer.json'),'-']
    t=time.monotonic()
    with tempfile.TemporaryDirectory(prefix='lean-idea-only-') as cwd:
        with (out/'events.jsonl').open('w') as o,(out/'stderr.txt').open('w') as e:
            try:c=subprocess.run(cmd,input=prompt,text=True,cwd=cwd,stdout=o,stderr=e,timeout=360).returncode
            except subprocess.TimeoutExpired:c=124
    elapsed=time.monotonic()-t
    events=[]
    for l in (out/'events.jsonl').read_text().splitlines():
        try:events.append(json.loads(l))
        except json.JSONDecodeError:pass
    tools=[e['item']['type'] for e in events if isinstance(e.get('item'),dict) and e['item'].get('type') not in {'agent_message','reasoning','todo_list','plan'}]
    try:a=json.loads((out/'answer.json').read_text());idea=a['idea']
    except Exception:idea=None
    valid=c==0 and isinstance(idea,str) and not tools
    (out/'metadata.json').write_text(json.dumps(dict(task=r['id'],arm='luna-idea-only',model='gpt-6-luna',effort='low',cli_returncode=c,tool_items=tools,valid=valid,generated_seconds=elapsed,prompt_sha256=hashlib.sha256(prompt.encode()).hexdigest(),usage=[e.get('usage') for e in events if e.get('type')=='turn.completed']),indent=2)+'\n')
    print(r['id'],valid,f'{elapsed:.1f}s',flush=True)
    return r['id'],idea if valid else None

if __name__=='__main__':
    rows=json.loads((ROOT/'panel.json').read_text())
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:results=dict(pool.map(run,rows))
    assert all(isinstance(v,str) for v in results.values())
    (ROOT/'idea-only-handoffs.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n')
